import random

def strategy(history, rng):
    if not history:
        return 'C'

    n = len(history)
    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_last = me[-1]
    opp_last = opp[-1]

    opp_rate = (opp_c + 1.0) / (n + 2.0)

    # Endgame exploitation: last few rounds, defect against cooperative partners.
    remaining = 100 - n
    if remaining <= 2:
        if opp_rate > 0.5:
            return 'D'
        return 'C'

    # If opponent has been constantly defecting, defect.
    if opp_rate <= 0.22:
        return 'D'

    # Fully cooperative partner: stay cooperative, with rare cheap probes
    # placed not-too-late so we can repair before the end.
    if opp_d == 0:
        if 20 <= n <= 80 and n % 23 == 0 and my_last == 'C':
            return 'D'
        return 'C'

    # Look at recent window.
    w = 10 if n >= 10 else n
    recent_opp = opp[-w:]
    recent_def = recent_opp.count('D')
    recent_c = w - recent_def

    # Aggressively punish sustained defection.
    if recent_def >= 6:
        return 'D'

    # Count opponent's consecutive defections.
    streak = 0
    for x in reversed(opp):
        if x == 'D':
            streak += 1
        else:
            break

    opp_c_streak = 0
    for x in reversed(opp):
        if x == 'C':
            opp_c_streak += 1
        else:
            break

    if opp_last == 'D':
        # Short punishment, then forgiveness to restore cooperation.
        if streak >= 3:
            return 'D'
        if streak == 2:
            # Give one more D if we haven't just defected, else cooperate to break cycle.
            if my_last == 'D':
                return 'C'
            return 'D'
        # streak == 1: single defection
        if opp_rate >= 0.55:
            # Forgive isolated defection frequently.
            if recent_def <= 1:
                if rng.random() < 0.75:
                    return 'C'
            if rng.random() < 0.45:
                return 'C'
            return 'D'
        # Moderately cooperative: retaliate unless we already defected.
        if my_last == 'D':
            return 'C'
        return 'D'

    # Opponent last cooperated.
    if my_last == 'D':
        # Return to cooperation promptly to repair.
        # But if partner is highly exploitable (rarely punishes), press briefly.
        if opp_rate >= 0.8 and streak == 0 and n < 90:
            # Check whether our previous defection was punished: if opp stayed C,
            # partner is a pushover; press one more time occasionally.
            if opp_c_streak >= 2 and rng.random() < 0.35:
                return 'D'
        return 'C'

    # Mutual cooperation ongoing. Occasionally probe a moderately cooperative partner.
    if opp_rate >= 0.6 and n >= 15 and n <= 85:
        if rng.random() < 0.04:
            return 'D'

    return 'C'
